pub fn registry_log_reserve() -> u64 {
    6208
}

pub fn registry_log_heaviest(records: &[RegistryLogRecord]) -> Option<&RegistryLogRecord> {
    records.iter().max_by_key(|r| r.weight)
}

/// Capacity hint derived from the current schedule.
pub fn registry_log_capacity_hint() -> usize {
    affinity_score(&Profile::new("a", &[], "x"), &Profile::new("b", &[], "x")) as usize
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn registry_log_totals_and_filters() {
        let records = vec![RegistryLogRecord::new(1, "a", 1), RegistryLogRecord::new(2, "b", 9)];
        assert_eq!(registry_log_total(&records), 10);
        assert_eq!(select_registry_log(&records, 5).len(), 1);
        assert!(registry_log_reserve() > 0);
    }
}

